namespace TheSingularityWorkshop.Economy;
/// <summary>Represents a monetary amount without coupling the economy to a payment provider.</summary>
public readonly record struct Money { public Money(decimal amount,string currency){Amount=amount;Currency=NormalizeCurrency(currency);} public decimal Amount{get;} public string Currency{get;} public static Money Zero(string currency)=>new(0m,currency); public Money Add(Money other)=>new(Amount+RequireCurrency(other).Amount,Currency); public Money Subtract(Money other)=>new(Amount-RequireCurrency(other).Amount,Currency); public Money Multiply(decimal factor)=>new(Amount*factor,Currency); private Money RequireCurrency(Money other)=>string.Equals(Currency,other.Currency,StringComparison.OrdinalIgnoreCase)?other:throw new InvalidOperationException($"Currency mismatch: {Currency} and {other.Currency}."); private static string NormalizeCurrency(string currency){ArgumentException.ThrowIfNullOrWhiteSpace(currency);var normalized=currency.Trim().ToUpperInvariant();if(normalized.Length!=3)throw new ArgumentException("Currency must use a three-letter code.",nameof(currency));return normalized;} }